/**
 * Types for src/data/cards.json (generated by tools/extract_cards.py).
 * Card types appear in this order within an archetype; guides come first in the deck.
 */
export const CARD_TYPES = ['guide', 'archetype', 'technology', 'organisation', 'activation', 'case'] as const
export type CardType = (typeof CARD_TYPES)[number]

export const SDG_IDS = [8, 9, 10, 11, 12, 13, 15, 16] as const
export type SdgId = (typeof SDG_IDS)[number]

export interface ImagePair {
  /** Paths relative to public/, e.g. "cards/full/a1-archetype-front.webp" (893×1259). */
  full: string
  /** 298×420 */
  thumb: string
}

interface CardBase {
  id: string
  type: CardType
  archetypeId: string | null
  title: string
  images: { front: ImagePair; back: ImagePair }
  /** 1-based page numbers in the print PDF. */
  pages: { front: number; back: number }
}

export type PlayMode = 'inspiration-1' | 'inspiration-2' | 'strategy'

export interface GuideCard extends CardBase {
  type: 'guide'
  archetypeId: null
  mode: PlayMode
  steps: { text: string; subItems: string[] }[]
  what: string
  when: string
}

export interface ArchetypeCard extends CardBase {
  type: 'archetype'
  archetypeId: string
  intro: string
  points: string[]
  sustainabilityLink: string
}

export interface TechnologyCard extends CardBase {
  type: 'technology'
  archetypeId: string
  points: string[]
  tip: string
}

export interface OrganisationCard extends CardBase {
  type: 'organisation'
  archetypeId: string
  points: string[]
  valueProposition: string
}

export interface ActivationCard extends CardBase {
  type: 'activation'
  archetypeId: string
  question: string
  caseOverview: string[]
}

export interface CaseCard extends CardBase {
  type: 'case'
  archetypeId: string
  summary: string
  takeaways: { technology: string; organisation: string; sustainability: string }
}

export type Card = GuideCard | ArchetypeCard | TechnologyCard | OrganisationCard | ActivationCard | CaseCard

export interface Archetype {
  id: string
  number: number
  title: string
  /** Deck colour as #RRGGBB. */
  colour: string
  sdgs: SdgId[]
}

export interface DeckMeta {
  title: string
  publisher: string
  language: string
  cardFormat: string
  source: string
  extracted: string
  corrections: { from: string; to: string }[]
  strayHyphensFixed: string[]
  contentIssues: string[]
}

export interface Deck {
  meta: DeckMeta
  archetypes: Archetype[]
  cards: Card[]
}
